# Let me check if connected regions of 0s define these areas
# Or maybe it's: connected components of 1s that are surrounded by 0s become 3

def find_enclosed_1s(grid):
    H, W = len(grid), len(grid[0])

    # Find connected components of 1s that touch the border
    border_reachable = set()
    queue = []

    # Add all boundary 1s
    for r in range(H):
        for c in [0, W-1]:
            if grid[r][c] == 1:
                queue.append((r, c))
                border_reachable.add((r, c))
    for r in [0, H-1]:
        for c in range(1, W-1):
            if grid[r][c] == 1:
                queue.append((r, c))
                border_reachable.add((r, c))

    visited = set()
    while queue:
        r, c = queue.pop(0)
        for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == 1 and (nr, nc) not in visited:
                visited.add((nr, nc))
                border_reachable.add((nr, nc))
                queue.append((nr, nc))

    # Enclosed 1s are all cells with value 1 that are NOT border-reachable
    enclosed = {
        (r, c) for r in range(H) for c in range(W)
        if grid[r][c] == 1 and (r, c) not in border_reachable
    }
    return enclosed

